// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public {
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function testFuzz_property(bytes32 guessedHash, address guesser) public {
        vm.assume(guesser != address(0));

        // Fund the guesser so they can stake the required 1 ether.
        vm.deal(guesser, 1 ether);

        // The guesser locks in a guess at the current block. The reference stores
        // guesses[guesser].block = block.number + 1, and settle should revert until
        // block.number > that stored block.
        vm.prank(guesser);
        c.lockInGuess{value: 1 ether}(guessedHash);

        // Immediately attempt to settle in the SAME block. On the reference this must
        // revert because block.number is not yet greater than block.number + 1.
        bool ok;
        vm.prank(guesser);
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference must revert; the mutant will not, so this assertion fails for the bug.
        assertTrue(!ok, "settle must revert before the target block (lack of time check is a security bug)");
    }
}
